#ifndef CONFIG_H
#define CONFIG_H

#include <string>
#include <string_view>
#include <memory>
#include <unordered_map>
#include <shared_mutex>
#include <functional>
#include <yaml-cpp/yaml.h>

namespace config {

class VarBase {
public:
    virtual ~VarBase() = default;
    std::string_view Name() const noexcept { return name_; }
    std::string_view Description() const noexcept { return description_; }
    virtual std::string ToString() const noexcept = 0;
    virtual void FromString(std::string_view str) = 0;

protected:
    VarBase(const std::string& name, const std::string& description)
        : name_(name), description_(description) {}

private:
    std::string name_;
    std::string description_;
};

template<typename T, typename FromStr, typename ToStr>
class Var : public VarBase {
public:
    using Ptr = std::shared_ptr<Var<T, FromStr, ToStr>>;

    Var(const std::string& name, const T& default_val, const std::string& description)
        : VarBase(name, description), val_(default_val) {}

    std::string ToString() const noexcept override {
        return ToStr()(val_);
    }

    void FromString(std::string_view str) override {
        val_ = FromStr()(str);
    }

    T GetValue() const noexcept {
        return val_;
    }

    void SetValue(const T& val) noexcept {
        std::unique_lock lock(mtx_);
        val_ = val;
        for (auto&& [key, listener] : listeners_) {
            listener(val);
        }
    }

    std::string_view TypeName() const noexcept {
        return typeid(T).name();
    }

    void RemoveListener(const std::uint64_t key) noexcept {
        std::unique_lock lock(mtx_);
        listeners_.erase(key);
    }

    std::uint64_t AddListener(OnChange listener) noexcept {
        static std::atomic<std::uint64_t> next_key = 0;
        std::unique_lock lock(mtx_);
        auto key = next_key++;
        listeners_.emplace(key, std::move(listener));
        return key;
    }

    void ClearListeners() noexcept {
        std::unique_lock lock(mtx_);
        listeners_.clear();
    }

private:
    mutable std::shared_mutex mtx_;
    T val_;
    std::unordered_map<std::uint64_t, OnChange> listeners_;
};

class Config {
public:
    using Ptr = std::shared_ptr<Config>;

    Config(const std::string& name) : name_(name) {}

    std::string_view Name() const noexcept { return name_; }

    template<typename T>
    typename Var<T, FromStr, ToStr>::Ptr Lookup(const std::string_view name, const T& default_val, const std::string_view description = "") {
        auto var_base = LookupBase(name);
        if (var_base) {
            return std::dynamic_pointer_cast<Var<T, FromStr, ToStr>>(var_base);
        }
        auto var = std::make_shared<Var<T, FromStr, ToStr>>(std::string(name), default_val, std::string(description));
        std::unique_lock lock(mtx_);
        vars_.emplace(std::string(name), var);
        return var;
    }

    template<typename T>
    typename Var<T, FromStr, ToStr>::Ptr Lookup(const std::string_view name) const {
        auto var_base = LookupBase(name);
        if (!var_base) {
            throw std::runtime_error("Variable not found");
        }
        auto var = std::dynamic_pointer_cast<Var<T, FromStr, ToStr>>(var_base);
        if (!var) {
            throw std::runtime_error("Type mismatch");
        }
        return var;
    }

    VarBase::Ptr LookupBase(std::string_view name) const noexcept {
        std::shared_lock lock(mtx_);
        auto it = vars_.find(name);
        if (it != vars_.end()) {
            return it->second;
        }
        return nullptr;
    }

    void LoadYaml(const YAML::Node& root) {
        ExtractMembers(root);
    }

    void Visit(std::function<void(VarBase::Ptr)> visitor) const noexcept {
        std::shared_lock lock(mtx_);
        for (auto&& [name, var] : vars_) {
            visitor(var);
        }
    }

private:
    using VarMap = std::unordered_map<std::string, VarBase::Ptr>;

    void ExtractMembers(const YAML::Node& root) {
        if (!root.IsMap()) {
            throw std::runtime_error("Root node is not a map");
        }
        for (auto&& [key, value] : root) {
            auto var_base = LookupBase(key.as<std::string>());
            if (var_base) {
                var_base->FromString(value.as<std::string>());
            }
        }
    }

    mutable std::shared_mutex mtx_;
    std::string name_;
    VarMap vars_;
};

}
#endif // CONFIG_H

#include "config.h"
#include <stdexcept>
#include <sstream>
#include <typeinfo>
#include <atomic>

namespace config {

template<typename T, typename FromStr, typename ToStr>
Var<T, FromStr, ToStr>::Var(const std::string& name, const T& default_val, const std::string& description)
    : VarBase(name, description), val_(default_val) {}

}
